
from pydantic import BaseModel, Field
from datetime import datetime


class LoginRequest(BaseModel):
    # Credentials submitted by the user.
    username: str = Field(min_length=1)
    password: str = Field(min_length=1)


class UnlockRequest(BaseModel):
    # Lock identifier and credential.
    lock_id: str = Field(min_length=1)
    lock_password: str = Field(min_length=1)

    # Timestamp generated by the Smart Lock.
    timestamp: int

    # Unique value used to prevent replay attacks.
    nonce: str = Field(min_length=16)


class AdminUserCreate(BaseModel):
    # Information required to create a regular user.
    username: str = Field(min_length=1, max_length=100)
    password: str = Field(min_length=1)


class AdminUserResponse(BaseModel):
    # Public user information returned by admin APIs.
    id: int
    username: str
    role: str
    is_active: bool
    created_at: datetime | None = None


class UserStatusUpdate(BaseModel):
    # New activation status for the user.
    is_active: bool


class AdminLockCreate(BaseModel):
    # Require a lock identifier and a password.
    lock_id: str = Field(min_length=1, max_length=100)
    password: str = Field(min_length=1)


class AdminLockResponse(BaseModel):
    # Return lock information without exposing its password hash.
    id: int
    lock_id: str
    is_active: bool
    created_at: datetime | None = None


class LockStatusUpdate(BaseModel):
    # Define the new active status of the lock.
    is_active: bool


class UserLockPermissionResponse(BaseModel):
    # Information about a user's permission to access a lock.
    id: int
    user_id: int
    lock_id: int
    created_at: datetime


class AdminAuditLogResponse(BaseModel):
    # Security event information visible to administrators.
    id: int
    timestamp: datetime
    username: str | None = None
    ip_address: str | None = None
    event_type: str
    result: str
    reason: str | None = None
